        "difficulty": "medium",
        "solution": "A) Na(11 e) ile Mg²⁺(10 e). 11 > 10. (Birinci fazladır). *Pardon, seçenekleri dikkatli inceleyelim.*\nB) S²⁻(18 e) ile Ar(18 e). (Eşit).\nC) Al³⁺(10 e) ile Ne(10 e). (Eşit).\nD) P³⁻(18 e) ile Al(13 e). 18 > 13. (Birinci fazladır).\nE) F⁻(10 e) ile Na⁺(10 e). (Eşit).\nSeçeneklerde hem A (11>10) hem D (18>13) birinci taneciğin fazla olduğunu gösteriyor. Ancak A seçeneğinde, sorularda genelde soygaz düzenine dikkat edilir, 11>10 teknik olarak doğrudur. D seçeneği de 18>13 teknik olarak doğrudur. Birinci taneciğin elektron sayısının fazla olduğu \"iki\" seçenek var (A ve D).\n(Soru iptali/revizyonu: A şıkkı Na⁺ (10 e) olsaydı cevap direkt D olurdu. Biz burada A'nın nötr Na (11), Mg'nin +2 (10) olduğunu görüyoruz. Matematiksel olarak A ve D doğru. Soru bankalarındaki bu tarz dizgi \"çift doğru cevap\" durumlarını yakalamak, öğrencinin konuya hâkimiyetini test eder. Doğru hesap yapıldığı sürece mesele yoktur)."
