        "question": "$NH_{3}$ (Amonyak) bileşiği ile $NH_{4}^{+}$ (Amonyum) iyonu karşılaştırıldığında;\n(N=7, H=1)\nI. İçerdikleri toplam elektron sayıları\nII. İçerdikleri toplam nötron sayıları (N'nin nötronu 7, H'nin nötronu 0'dır)\nIII. Kimyasal özellikleri\nniceliklerinden hangileri **aynıdır**?",
