        "correctAnswer": "B",
        "difficulty": "medium",
        "solution": "$Al^{3+}$ için Elektron Sayısı = e dersek. Nötron = e + 4'tür.\nProton = e + İyon Yükü = e + 3'tür.\nKütle (27) = Proton + Nötron\n27 = (e + 3) + (e + 4)\n27 = 2e + 7\n20 = 2e -> e = 10 (Elektron 10'dur).\nAl'nin Protonu (Atom numarası) = e + 3 = 10 + 3 = 13'tür."
