        "solution": "X: 2A grubunda (Toprak alkali metal). Bileşiklerinde 2 elektron \"verir\" ve +2 değerlik alır. (III doğru).\nY: 6A grubunda (Kalkojen, ametal). Bileşiklerinde 2 elektron \"alır\" ve -2 değerlik alır. (III doğru).\nMetal ve ametal arasında elektron alışverişiyle (biri verir, biri alır) \"İyonik bağ\" oluşur. (I doğru).\nFormül yazılırken yükler çaprazlanır: $X^{2+}$ ve $Y^{2-}$ -> Çaprazlarsak $X_2Y_2$, sadeleştirirsek formül $XY$ olur. $X_2Y$ yanlıştır (II yanlış). Cevap I ve III."
