        "id": "KIM-TYT-K02-T28-S04",
        "question": "Kalsiyum ($Ca$) atomu $Ca^{2+}$ iyonu hâline gelirken;\nI. Atom çapı (hacmi)\nII. Çekirdek çekim gücü (Proton sayısı)\nIII. Bir elektron başına düşen çekirdek çekim kuvveti\nniceliklerindeki değişim aşağıdakilerin hangisinde doğru verilmiştir?\n| | I | II | III |\n|---|---|---|---|\n| A) | Küçülür | Azalır | Artar |\n| B) | Büyür | Değişmez | Azalır |\n| C) | Küçülür | Değişmez | Artar |\n| D) | Küçülür | Değişmez | Azalır |\n| E) | Büyür | Artar | Artar |",
        "options": [],
