        "correctAnswer": "B",
        "difficulty": "hard",
        "solution": "Kovalent bağda iki atomun elektron bulutları birbirinin içine geçer (kesişir). Bu yüzden çekirdekler birbirine oldukça yaklaşır ve yarıçap (mesafe/2) nispeten KÜÇÜKTÜR. Van der Waals etkileşiminde ise bağımsız iki molekül (örneğin iki tane Cl2 molekülü yan yana dururken) veya iki soygaz atomu birbirine sadece \"teğet\" geçer, iç içe geçmezler. Bu yüzden çekirdekler arası mesafe daha fazladır.\nDolayısıyla Van der Waals yarıçapı, daima Kovalent yarıçaptan DAHA BÜYÜKTÜR. ($Kovalent < VdW$). Cevap B'dir."
